use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let mut map = std::collections::BTreeMap::new();
    if let Value::Array(arr) = input {
        for row in arr {
            if let Value::Array(pair) = row {
                if let (Value::Number(key), Value::Number(val)) = (&pair[0], &pair[1]) {
                    if let (Some(k), Some(v)) = (key.as_i64(), val.as_i64()) {
                        *map.entry(k).or_insert(0) += v;
                    }
                }
            }
        }
    }
    let mut result = Vec::new();
    for (key, val) in map {
        result.push(json!([key, val]));
    }
    Value::Array(result)
}
